/* ============================================================
   COLÔNIA AURORA — interface
   ============================================================ */

:root {
  --bg: #05060d;
  --bg-2: #070a15;
  --panel: rgba(9, 15, 29, 0.78);
  --panel-solid: #0a1020;
  --cyan: #6ee7ff;
  --cyan-soft: #a9f6ff;
  --violet: #b58cff;
  --gold: #ffd166;
  --green: #7dffb2;
  --orange: #ff9a63;
  --red: #ff6b81;
  --text: #e9f1ff;
  --muted: #8b9abd;
  --faint: #5d6a88;
  --line: rgba(126, 190, 255, 0.16);
  --line-strong: rgba(126, 190, 255, 0.36);
  --font: "Segoe UI", "Avenir Next", "Helvetica Neue", system-ui, sans-serif;
  --mono: "SFMono-Regular", "Cascadia Mono", "Roboto Mono", Menlo, Consolas, monospace;
  --r: 14px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button { font-family: inherit; }
button, [role="button"] { -webkit-tap-highlight-color: transparent; }
.hidden { display: none !important; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }

#app { position: fixed; inset: 0; overflow: hidden; }

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  background: #05060d;
  touch-action: none;
  cursor: crosshair;
}

kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 19px;
  height: 19px;
  padding: 0 5px;
  border: 1px solid rgba(150, 200, 255, 0.24);
  border-bottom-color: rgba(150, 200, 255, 0.4);
  border-radius: 5px;
  background: rgba(10, 18, 34, 0.9);
  color: #b9caea;
  font-family: var(--mono);
  font-size: 10px;
  line-height: 1;
  letter-spacing: 0.02em;
}

/* ============================================================
   TITLE
   ============================================================ */

#title-screen {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  flex-direction: column;
  padding: clamp(18px, 3vw, 38px) clamp(20px, 5vw, 72px) clamp(14px, 2.4vw, 28px);
  background:
    linear-gradient(90deg, rgba(4, 6, 14, 0.94) 0%, rgba(4, 6, 14, 0.72) 38%, rgba(4, 6, 14, 0.16) 72%, rgba(4, 6, 14, 0.42) 100%),
    radial-gradient(ellipse at 20% 80%, rgba(110, 231, 255, 0.07), transparent 55%),
    radial-gradient(ellipse at 85% 15%, rgba(181, 140, 255, 0.08), transparent 55%);
  pointer-events: auto;
}

#title-screen::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.014) 0 1px, transparent 1px 3px);
  opacity: 0.55;
  mix-blend-mode: overlay;
}

.title-grain {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.25;
  background-image:
    radial-gradient(circle at 12% 24%, rgba(255,255,255,.05) 0 1px, transparent 1.6px),
    radial-gradient(circle at 62% 78%, rgba(255,255,255,.04) 0 1px, transparent 1.6px);
  background-size: 170px 170px, 230px 230px;
}

.title-topline {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.26em;
  color: #7f8fb2;
  position: relative;
  z-index: 2;
}

.title-brand { display: flex; align-items: center; gap: 9px; color: #b8c8e8; }
.brand-orbit {
  width: 17px; height: 17px; border-radius: 50%;
  border: 1px solid rgba(110, 231, 255, 0.7);
  position: relative;
  box-shadow: 0 0 14px rgba(110, 231, 255, 0.35);
}
.brand-orbit::after {
  content: ""; position: absolute; width: 5px; height: 5px; border-radius: 50%;
  background: var(--cyan); top: -2px; right: -1px; box-shadow: 0 0 8px var(--cyan);
}
.title-version { color: #647293; }

.title-inner {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1.12fr) minmax(0, 0.88fr);
  align-items: center;
  gap: 40px;
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  position: relative;
  z-index: 2;
}

.title-copy { padding-left: clamp(0px, 2vw, 26px); }

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-family: var(--mono);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.28em;
  color: var(--cyan);
  margin-bottom: clamp(14px, 2.4vw, 26px);
  text-transform: uppercase;
}
.eyebrow-dot {
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 10px var(--cyan), 0 0 24px rgba(110, 231, 255, 0.5);
  animation: pulse 2.4s ease-in-out infinite;
}

.logo {
  margin: 0;
  font-size: clamp(58px, 9.2vw, 132px);
  line-height: 0.78;
  font-weight: 900;
  letter-spacing: -0.055em;
  display: flex;
  flex-direction: column;
  text-transform: uppercase;
}
.logo span {
  color: transparent;
  -webkit-text-stroke: 1.5px rgba(206, 228, 255, 0.62);
  font-weight: 800;
  letter-spacing: 0.015em;
  text-shadow: 0 0 40px rgba(110, 231, 255, 0.12);
}
.logo strong {
  font-weight: 900;
  background: linear-gradient(100deg, #e8fbff 0%, #6ee7ff 32%, #9f8cff 68%, #ff9ad5 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 32px rgba(110, 231, 255, 0.28));
  letter-spacing: -0.02em;
}

.tagline {
  margin: clamp(16px, 2.6vw, 30px) 0 clamp(22px, 3.4vw, 40px);
  font-size: clamp(14px, 1.35vw, 18px);
  line-height: 1.65;
  color: #a8b8d8;
  max-width: 490px;
  letter-spacing: 0.01em;
}

.title-actions { display: flex; gap: 12px; flex-wrap: wrap; align-items: center; }

.btn {
  --btn-accent: var(--cyan);
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  height: 50px;
  padding: 0 26px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--text);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  cursor: pointer;
  border-radius: 4px;
  clip-path: polygon(11px 0, 100% 0, 100% calc(100% - 11px), calc(100% - 11px) 100%, 0 100%, 0 11px);
  transition: transform 0.16s ease, box-shadow 0.2s ease, background 0.2s ease, color 0.2s ease;
}
.btn:hover { transform: translateY(-2px); }
.btn:active { transform: translateY(0); }
.btn:focus-visible { outline: 2px solid var(--cyan); outline-offset: 3px; }

.btn-primary {
  background: linear-gradient(120deg, #bff8ff 0%, #6ee7ff 46%, #8d9bff 100%);
  color: #04121c;
  box-shadow: 0 0 0 1px rgba(110, 231, 255, 0.35), 0 10px 34px rgba(66, 200, 255, 0.24);
  min-width: 190px;
}
.btn-primary:hover {
  box-shadow: 0 0 0 1px rgba(169, 246, 255, 0.7), 0 14px 44px rgba(66, 200, 255, 0.4);
  background: linear-gradient(120deg, #dcfdff 0%, #8bf0ff 46%, #a49cff 100%);
}
.btn-glyph { font-size: 10px; transform: translateY(-1px); }

.btn-ghost {
  border-color: rgba(150, 200, 255, 0.26);
  background: rgba(10, 18, 34, 0.55);
  color: #c7d7f5;
  backdrop-filter: blur(6px);
}
.btn-ghost:hover { border-color: rgba(150, 220, 255, 0.55); background: rgba(16, 30, 52, 0.75); color: #fff; }
.btn-ghost.small { height: 36px; padding: 0 16px; font-size: 10px; letter-spacing: 0.14em; }
.btn-danger { border-color: rgba(255, 107, 129, 0.35); background: rgba(60, 12, 24, 0.5); color: #ffb3c0; }
.btn-danger:hover { background: rgba(90, 16, 34, 0.7); }

.title-hints {
  display: flex;
  gap: 20px;
  flex-wrap: wrap;
  margin-top: clamp(22px, 3.4vw, 38px);
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  color: #6f7e9f;
}
.title-hints b { color: #b9ccef; font-weight: 700; }

.title-aside { display: flex; justify-content: flex-end; align-items: flex-end; align-self: end; padding-bottom: 5vh; }

.system-card {
  width: min(330px, 100%);
  padding: 20px 22px 18px;
  border: 1px solid rgba(126, 190, 255, 0.18);
  background: linear-gradient(155deg, rgba(13, 21, 40, 0.74), rgba(7, 11, 22, 0.62));
  backdrop-filter: blur(14px);
  border-radius: 10px;
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 18px 100%, 0 calc(100% - 18px));
}
.card-kicker {
  display: flex; align-items: center; justify-content: space-between;
  font-family: var(--mono); font-size: 9px; letter-spacing: 0.24em; color: var(--cyan);
}
.live-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--green); box-shadow: 0 0 10px var(--green); animation: pulse 2s infinite; }
.system-orbits {
  position: relative;
  height: 108px;
  margin: 14px 0 6px;
  border-bottom: 1px solid rgba(126, 190, 255, 0.12);
  overflow: hidden;
}
.system-orbits::before,
.system-orbits::after {
  content: ""; position: absolute; left: 50%; top: 54%; transform: translate(-50%, -50%);
  border: 1px solid rgba(110, 231, 255, 0.13); border-radius: 50%;
}
.system-orbits::before { width: 300px; height: 88px; }
.system-orbits::after { width: 210px; height: 62px; }
.sys-planet { position: absolute; border-radius: 50%; }
.sys-planet::after { content: ""; position: absolute; inset: 0; border-radius: 50%; box-shadow: inset -3px -3px 6px rgba(0,0,0,.55); }
.p1 { width: 8px; height: 8px; left: 31%; top: 49%; background: #8e9bff; box-shadow: 0 0 10px #8e9bff; }
.p2 { width: 11px; height: 11px; left: 22%; top: 27%; background: #ff8a5c; box-shadow: 0 0 12px rgba(255,138,92,.8); }
.p3 { width: 13px; height: 13px; left: 72%; top: 66%; background: #63e6b0; box-shadow: 0 0 12px rgba(99,230,176,.7); }
.p4 { width: 10px; height: 10px; left: 83%; top: 31%; background: #9fe8ff; box-shadow: 0 0 12px rgba(159,232,255,.8); }
.p5 { width: 16px; height: 16px; left: 59%; top: 18%; background: linear-gradient(140deg, #ffe0a3, #e08a4a); box-shadow: 0 0 16px rgba(255,195,107,.55); }
.system-names {
  display: flex; justify-content: space-between;
  font-family: var(--mono); font-size: 8px; letter-spacing: 0.12em; color: #7080a3;
}
.system-card p { margin: 13px 0 0; font-size: 11.5px; line-height: 1.6; color: #7f90b4; }

.title-footer {
  display: flex; justify-content: space-between; align-items: center;
  font-family: var(--mono); font-size: 9px; letter-spacing: 0.2em; color: #536180;
  position: relative; z-index: 2;
}
.footer-left { display: flex; align-items: center; gap: 8px; }
.scan-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 8px var(--cyan); }

/* ============================================================
   HUD / TOP BAR
   ============================================================ */

#hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; }
#hud > * { pointer-events: auto; }

#topbar {
  position: absolute;
  top: 12px; left: 12px; right: 12px;
  display: flex; align-items: center; gap: 14px;
  padding: 9px 12px 9px 14px;
  background: linear-gradient(100deg, rgba(8, 14, 27, 0.86), rgba(7, 11, 22, 0.68));
  border: 1px solid var(--line);
  border-radius: 12px;
  backdrop-filter: blur(16px);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.32), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  pointer-events: auto;
}

.brand-block { display: flex; align-items: center; gap: 11px; flex: 0 0 auto; }
.brand-mark {
  position: relative; width: 34px; height: 34px; border-radius: 50%;
  display: grid; place-items: center;
  border: 1px solid rgba(110, 231, 255, 0.28);
  background: radial-gradient(circle at 35% 30%, rgba(110,231,255,.26), rgba(7,12,24,.7));
}
.bm-ring { position: absolute; width: 20px; height: 9px; border: 1px solid rgba(181,140,255,.65); border-radius: 50%; transform: rotate(-28deg); }
.bm-core { width: 7px; height: 7px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 12px var(--cyan); }
.brand-name { font-size: 11px; font-weight: 900; letter-spacing: 0.22em; color: #dbe9ff; }
.brand-sub {
  margin-top: 3px;
  font-family: var(--mono); font-size: 8.5px; letter-spacing: 0.1em; color: #7585a8;
  white-space: nowrap;
}
.brand-sub #hud-planet { color: var(--cyan); font-weight: 700; }
.brand-sub .sep { margin: 0 6px; color: #3e4a68; }

.resource-bar { display: flex; align-items: center; gap: 4px; flex: 1 1 auto; justify-content: center; min-width: 0; overflow: hidden; }
.res-chip {
  display: flex; align-items: center; gap: 7px;
  padding: 6px 9px;
  border: 1px solid rgba(126, 190, 255, 0.1);
  border-radius: 7px;
  background: rgba(14, 23, 41, 0.4);
  min-width: 0;
  transition: background 0.25s ease, border-color 0.25s ease;
}
.res-chip:hover { background: rgba(20, 34, 58, 0.6); border-color: rgba(126, 190, 255, 0.25); }
.res-icon { width: 16px; height: 16px; flex: 0 0 auto; }
.res-icon svg { width: 100%; height: 100%; }
.res-text { display: flex; flex-direction: column; line-height: 1; min-width: 0; }
.res-value { font-family: var(--mono); font-size: 12px; font-weight: 700; color: #e5f1ff; font-variant-numeric: tabular-nums; }
.res-label { font-family: var(--mono); font-size: 7px; letter-spacing: 0.15em; color: #63718f; margin-top: 3px; }
.res-chip[data-res="energy"] .res-icon { color: #ffd166; filter: drop-shadow(0 0 5px rgba(255,209,102,.5)); }
.res-chip[data-res="water"] .res-icon { color: #6ee7ff; filter: drop-shadow(0 0 5px rgba(110,231,255,.45)); }
.res-chip[data-res="food"] .res-icon { color: #7dffb2; filter: drop-shadow(0 0 5px rgba(125,255,178,.4)); }
.res-chip[data-res="materials"] .res-icon { color: #ff9a63; filter: drop-shadow(0 0 5px rgba(255,154,99,.4)); }
.res-chip[data-res="credits"] .res-icon { color: #b58cff; filter: drop-shadow(0 0 5px rgba(181,140,255,.45)); }
.res-chip[data-res="research"] .res-icon { color: #ff9ad5; filter: drop-shadow(0 0 5px rgba(255,154,213,.4)); }
.res-chip.pulse { animation: chipPulse 0.5s ease; }

.top-actions { display: flex; align-items: center; gap: 6px; flex: 0 0 auto; }
.icon-btn {
  display: flex; align-items: center; gap: 7px;
  height: 38px; padding: 0 10px;
  border: 1px solid rgba(126, 190, 255, 0.14);
  border-radius: 7px;
  background: rgba(13, 22, 40, 0.44);
  color: #b7c7e8;
  cursor: pointer;
  transition: all 0.16s ease;
  font-family: inherit;
}
.icon-btn:hover { border-color: rgba(110, 231, 255, 0.45); background: rgba(20, 38, 64, 0.72); color: #fff; transform: translateY(-1px); }
.icon-btn:active { transform: translateY(0); }
.ib-icon { width: 17px; height: 17px; display: block; }
.ib-icon svg { width: 100%; height: 100%; }
.ib-label { font-family: var(--mono); font-size: 8px; letter-spacing: 0.12em; font-weight: 700; }
.icon-btn kbd { min-width: 16px; height: 16px; font-size: 8px; }
.icon-btn.compact { width: 38px; padding: 0; justify-content: center; }
.icon-btn.active { border-color: rgba(110,231,255,.5); background: rgba(25,50,80,.7); color: #fff; }

/* ============================================================
   SIDE PANELS
   ============================================================ */

.panel {
  background: linear-gradient(155deg, rgba(10, 17, 32, 0.84), rgba(7, 11, 22, 0.68));
  border: 1px solid var(--line);
  border-radius: var(--r);
  backdrop-filter: blur(16px);
  box-shadow: 0 16px 50px rgba(0, 0, 0, 0.32), inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.side-panel {
  position: absolute;
  top: 84px;
  width: 246px;
  padding: 13px 14px 12px;
}
#quest-panel { left: 12px; }
#colony-panel { right: 12px; }

.panel-head {
  display: flex; align-items: center; justify-content: space-between;
  padding-bottom: 9px;
  border-bottom: 1px solid rgba(126, 190, 255, 0.12);
  font-family: var(--mono); font-size: 8.5px; font-weight: 700; letter-spacing: 0.2em; color: #9fb2d6;
}
.panel-tag {
  padding: 3px 6px;
  border: 1px solid rgba(110, 231, 255, 0.2);
  border-radius: 4px;
  background: rgba(110, 231, 255, 0.06);
  color: var(--cyan);
  font-size: 8px;
  letter-spacing: 0.1em;
}

.quest-list { display: flex; flex-direction: column; gap: 11px; margin-top: 11px; }
.quest-item { position: relative; }
.quest-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; }
.quest-title { font-size: 11.5px; line-height: 1.35; font-weight: 600; color: #d3e2ff; }
.quest-reward { font-family: var(--mono); font-size: 8px; color: var(--gold); white-space: nowrap; padding-top: 1px; }
.quest-sub { margin-top: 3px; font-family: var(--mono); font-size: 8px; letter-spacing: 0.05em; color: #6d7d9f; }
.quest-progress { margin-top: 6px; display: flex; align-items: center; gap: 7px; }
.quest-progress .meter { flex: 1; height: 3px; }
.quest-progress .meter span { background: linear-gradient(90deg, var(--cyan), var(--violet)); }
.quest-count { font-family: var(--mono); font-size: 8px; color: #7c8dae; min-width: 28px; text-align: right; }
.quest-item.done .quest-title { color: var(--green); text-decoration: line-through; opacity: 0.65; }
.quest-item.done .meter span { background: var(--green); }
.quest-empty { font-family: var(--mono); font-size: 9px; color: #5d6a88; letter-spacing: 0.08em; padding: 6px 0 2px; }

.meter { height: 4px; border-radius: 99px; background: rgba(126, 190, 255, 0.1); overflow: hidden; }
.meter span { display: block; height: 100%; border-radius: 99px; background: linear-gradient(90deg, var(--cyan), var(--green)); transition: width 0.4s ease; box-shadow: 0 0 8px rgba(110, 231, 255, 0.4); }

.colony-main { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 12px; }
.colony-stat { display: flex; flex-direction: column; gap: 4px; }
.cs-label { font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.14em; color: #657494; }
.cs-value { font-family: var(--mono); font-size: 18px; font-weight: 700; color: #e6f2ff; line-height: 1; }
.cs-value em { font-style: normal; font-size: 10px; color: #667696; margin-left: 2px; }
#colony-happy { color: var(--green); }
#colony-panel .meter { margin-top: 10px; }
.colony-sub { margin-top: 12px; font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.16em; color: #657494; }
.production-list { margin-top: 7px; display: flex; flex-direction: column; gap: 5px; min-height: 22px; }
.prod-row { display: flex; align-items: center; gap: 6px; font-family: var(--mono); font-size: 9px; color: #9fb0d0; }
.prod-row svg { width: 12px; height: 12px; }
.prod-row b { color: #d7e7ff; font-weight: 700; margin-left: auto; }
.prod-row .neg { color: var(--red); }
.prod-empty { font-family: var(--mono); font-size: 8.5px; color: #566481; }
.colony-foot {
  display: flex; justify-content: space-between; margin-top: 11px; padding-top: 9px;
  border-top: 1px solid rgba(126, 190, 255, 0.1);
  font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.08em; color: #63718f;
}

/* ============================================================
   HOTBAR / ACTION HINT
   ============================================================ */

.hotbar-wrap {
  position: absolute;
  left: 50%; bottom: 14px;
  transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  pointer-events: auto;
  z-index: 12;
}
.hotbar-title {
  display: flex; align-items: center; gap: 10px;
  font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.18em; color: #5f6e8f;
}
.hotbar-title span:last-child { color: var(--cyan); }
.hotbar { display: flex; gap: 6px; padding: 7px; border: 1px solid var(--line); border-radius: 12px; background: rgba(6, 11, 22, 0.78); backdrop-filter: blur(16px); box-shadow: 0 18px 50px rgba(0, 0, 0, 0.45); }
.tool-slot {
  position: relative;
  width: 58px; height: 62px;
  border: 1px solid rgba(126, 190, 255, 0.13);
  border-radius: 8px;
  background: linear-gradient(160deg, rgba(20, 33, 56, 0.55), rgba(8, 13, 25, 0.7));
  color: #aab9d8;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px;
  cursor: pointer;
  transition: transform 0.14s ease, border-color 0.16s ease, background 0.16s ease, color 0.16s ease;
}
.tool-slot:hover { border-color: rgba(110, 231, 255, 0.36); background: rgba(22, 40, 68, 0.75); color: #e3f1ff; transform: translateY(-2px); }
.tool-slot.selected {
  border-color: rgba(110, 231, 255, 0.72);
  background: linear-gradient(160deg, rgba(35, 76, 104, 0.65), rgba(16, 28, 50, 0.85));
  color: #f2fcff;
  transform: translateY(-3px);
  box-shadow: 0 0 0 1px rgba(110, 231, 255, 0.2), 0 8px 24px rgba(0, 0, 0, 0.4), 0 0 22px rgba(110, 231, 255, 0.14);
}
.tool-slot.selected::before {
  content: ""; position: absolute; left: 50%; top: -1px; transform: translateX(-50%);
  width: 22px; height: 2px; background: var(--cyan); box-shadow: 0 0 10px var(--cyan); border-radius: 99px;
}
.tool-slot.accent { color: #d9c4ff; }
.tool-icon { width: 21px; height: 21px; }
.tool-icon svg { width: 100%; height: 100%; }
.tool-name { font-family: var(--mono); font-size: 7px; letter-spacing: 0.1em; }
.tool-key {
  position: absolute; top: 4px; left: 5px;
  font-family: var(--mono); font-size: 7px; color: #5d6d8d;
}
.tool-slot.selected .tool-key { color: var(--cyan); }
.tool-badge {
  position: absolute; top: 4px; right: 4px;
  min-width: 14px; height: 14px; padding: 0 3px;
  display: grid; place-items: center;
  border-radius: 4px;
  background: rgba(110, 231, 255, 0.14);
  color: var(--cyan);
  font-family: var(--mono); font-size: 7.5px; font-weight: 700;
}
.tool-badge.empty { color: var(--red); background: rgba(255, 107, 129, 0.12); }
.seed-dot { width: 7px; height: 7px; border-radius: 50%; box-shadow: 0 0 8px currentColor; }

.action-hint {
  position: absolute; left: 50%; bottom: 122px;
  transform: translateX(-50%);
  display: flex; align-items: center; gap: 9px;
  padding: 8px 14px 8px 9px;
  border: 1px solid rgba(110, 231, 255, 0.24);
  border-radius: 99px;
  background: rgba(7, 13, 26, 0.82);
  backdrop-filter: blur(12px);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
  font-family: var(--mono); font-size: 9px; letter-spacing: 0.08em; color: #c9dcff;
  pointer-events: none;
  z-index: 11;
  white-space: nowrap;
  transition: opacity 0.2s ease;
}
.ah-key {
  display: grid; place-items: center;
  width: 22px; height: 22px; border-radius: 5px;
  background: rgba(110, 231, 255, 0.14);
  border: 1px solid rgba(110, 231, 255, 0.32);
  color: var(--cyan); font-size: 9px; font-weight: 700;
}
.ah-icon { width: 14px; height: 14px; color: var(--cyan); }
.ah-icon svg { width: 100%; height: 100%; }
.ah-text b { color: #fff; font-weight: 700; }
.action-hint.warn { border-color: rgba(255, 107, 129, 0.35); }
.action-hint.warn .ah-key { background: rgba(255,107,129,.13); border-color: rgba(255,107,129,.4); color: var(--red); }

/* seed picker */
.seed-picker {
  position: absolute; left: 50%; bottom: 164px;
  transform: translateX(-50%);
  display: flex; gap: 6px; align-items: center;
  padding: 7px;
  border: 1px solid rgba(126, 190, 255, 0.18);
  border-radius: 10px;
  background: rgba(7, 13, 26, 0.86);
  backdrop-filter: blur(14px);
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.4);
  z-index: 11;
}
.seed-option {
  display: flex; align-items: center; gap: 7px;
  padding: 5px 9px;
  border: 1px solid transparent;
  border-radius: 6px;
  background: rgba(20, 32, 54, 0.4);
  color: #9fb0d0;
  cursor: pointer;
  font-family: var(--mono); font-size: 8px; letter-spacing: 0.05em;
  transition: all 0.15s ease;
}
.seed-option:hover { background: rgba(30, 48, 76, 0.7); color: #fff; }
.seed-option.selected { border-color: rgba(110, 231, 255, 0.4); background: rgba(35, 76, 104, 0.4); color: #fff; }
.seed-option .seed-dot { width: 8px; height: 8px; }
.seed-option b { color: var(--cyan); font-size: 8px; }
.seed-option.empty b { color: var(--red); }

/* tooltip */
.tile-tip {
  position: absolute;
  z-index: 20;
  min-width: 150px; max-width: 230px;
  padding: 9px 11px;
  border: 1px solid rgba(126, 190, 255, 0.24);
  border-radius: 8px;
  background: rgba(6, 11, 22, 0.9);
  backdrop-filter: blur(12px);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.45);
  pointer-events: none;
  font-family: var(--mono);
  font-size: 9px;
  line-height: 1.5;
  color: #9fb2d4;
}
.tile-tip .tt-title { color: #e8f3ff; font-size: 10px; font-weight: 700; letter-spacing: 0.05em; margin-bottom: 2px; }
.tile-tip .tt-row { display: flex; justify-content: space-between; gap: 10px; }
.tile-tip .tt-row b { color: var(--cyan); font-weight: 700; }
.tile-tip .tt-ready { color: var(--gold); }

/* toasts */
.toasts {
  position: absolute;
  top: 88px; left: 50%;
  transform: translateX(-50%);
  display: flex; flex-direction: column; align-items: center; gap: 8px;
  z-index: 25;
  pointer-events: none;
  width: min(420px, calc(100vw - 24px));
}
.toast {
  display: flex; align-items: flex-start; gap: 10px;
  width: 100%;
  padding: 10px 14px;
  border: 1px solid rgba(126, 190, 255, 0.22);
  border-left: 2px solid var(--cyan);
  border-radius: 9px;
  background: linear-gradient(100deg, rgba(9, 17, 32, 0.95), rgba(8, 13, 25, 0.86));
  backdrop-filter: blur(14px);
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.45);
  animation: toastIn 0.35s cubic-bezier(0.2, 0.9, 0.3, 1.1);
  pointer-events: none;
}
.toast.out { animation: toastOut 0.3s ease forwards; }
.toast-icon { width: 22px; height: 22px; flex: 0 0 auto; color: var(--cyan); }
.toast-icon svg { width: 100%; height: 100%; }
.toast-body { min-width: 0; }
.toast-title { font-family: var(--mono); font-size: 8.5px; letter-spacing: 0.16em; color: #dff6ff; font-weight: 700; }
.toast-text { margin-top: 3px; font-size: 11px; line-height: 1.4; color: #9fb2d4; }
.toast.gold { border-left-color: var(--gold); }
.toast.gold .toast-icon { color: var(--gold); }
.toast.green { border-left-color: var(--green); }
.toast.green .toast-icon { color: var(--green); }
.toast.violet { border-left-color: var(--violet); }
.toast.violet .toast-icon { color: var(--violet); }
.toast.red { border-left-color: var(--red); }
.toast.red .toast-icon { color: var(--red); }

/* touch */
#touch-ui { display: none; }
.touch-action {
  width: 62px; height: 62px; border-radius: 50%;
  border: 1px solid rgba(110, 231, 255, 0.45);
  background: rgba(18, 40, 62, 0.68);
  color: var(--cyan);
  font-family: var(--mono); font-size: 18px; font-weight: 700;
  box-shadow: 0 8px 30px rgba(0,0,0,.35), inset 0 0 20px rgba(110,231,255,.12);
  backdrop-filter: blur(10px);
  cursor: pointer;
}
.touch-action:active { background: rgba(35, 80, 110, 0.8); transform: scale(0.95); }
#joystick {
  position: fixed; left: 20px; bottom: 112px;
  width: 108px; height: 108px; border-radius: 50%;
  border: 1px solid rgba(126, 190, 255, 0.2);
  background: rgba(9, 16, 30, 0.4);
  backdrop-filter: blur(8px);
  touch-action: none;
}
.joystick-base {
  position: absolute; inset: 18px; border-radius: 50%;
  border: 1px dashed rgba(126, 190, 255, 0.16);
}
.joystick-knob {
  position: absolute; left: 50%; top: 50%; width: 40px; height: 40px;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, rgba(169,246,255,.8), rgba(46,120,160,.65));
  border: 1px solid rgba(169, 246, 255, 0.55);
  box-shadow: 0 0 20px rgba(110, 231, 255, 0.25);
}
#touch-action { position: fixed; right: 22px; bottom: 120px; }

/* ============================================================
   OVERLAYS
   ============================================================ */

.screen.overlay {
  position: absolute;
  inset: 0;
  z-index: 50;
  display: flex; align-items: center; justify-content: center;
  padding: 22px;
  background: rgba(3, 5, 12, 0.72);
  backdrop-filter: blur(12px);
  animation: fadeIn 0.22s ease;
}

.overlay-shell {
  width: min(1040px, 100%);
  max-height: calc(100vh - 44px);
  overflow: auto;
  padding: clamp(18px, 2.4vw, 30px);
  border: 1px solid rgba(126, 190, 255, 0.22);
  border-radius: 16px;
  background:
    radial-gradient(ellipse at 0% 0%, rgba(110, 231, 255, 0.05), transparent 46%),
    linear-gradient(160deg, rgba(11, 18, 34, 0.97), rgba(6, 10, 20, 0.97));
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  scrollbar-width: thin;
  scrollbar-color: rgba(110,231,255,.3) transparent;
}
.overlay-shell.wide { width: min(1180px, 100%); }
.overlay-shell.narrow { width: min(480px, 100%); }

.overlay-head {
  display: flex; align-items: flex-start; justify-content: space-between; gap: 18px;
  padding-bottom: 16px;
  border-bottom: 1px solid rgba(126, 190, 255, 0.14);
}
.overlay-kicker { font-family: var(--mono); font-size: 8.5px; letter-spacing: 0.24em; color: var(--cyan); }
.overlay-head h2 {
  margin: 7px 0 0;
  font-size: clamp(24px, 3vw, 38px);
  font-weight: 900;
  letter-spacing: -0.03em;
  line-height: 1;
  background: linear-gradient(100deg, #f2fbff, #8bd8ff 60%, #b58cff);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.overlay-head-right { display: flex; align-items: center; gap: 14px; padding-top: 4px; }
.overlay-note { font-family: var(--mono); font-size: 8.5px; letter-spacing: 0.12em; color: #7384a6; }
.overlay-foot {
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  margin-top: 18px; padding-top: 14px;
  border-top: 1px solid rgba(126, 190, 255, 0.12);
  font-family: var(--mono); font-size: 8.5px; letter-spacing: 0.08em; color: #6d7d9f;
}
.overlay-key { display: flex; align-items: center; gap: 6px; }

/* ============================================================
   BUILD MENU
   ============================================================ */

.build-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin-top: 18px;
}
.build-card {
  position: relative;
  display: flex; flex-direction: column;
  gap: 9px;
  padding: 14px;
  border: 1px solid rgba(126, 190, 255, 0.14);
  border-radius: 11px;
  background: linear-gradient(165deg, rgba(21, 34, 57, 0.55), rgba(8, 13, 26, 0.6));
  color: var(--text);
  text-align: left;
  cursor: pointer;
  transition: all 0.17s ease;
  overflow: hidden;
  font-family: inherit;
}
.build-card::after {
  content: ""; position: absolute; inset: 0;
  background: linear-gradient(120deg, transparent 30%, rgba(110, 231, 255, 0.05) 50%, transparent 70%);
  transform: translateX(-100%);
  transition: transform 0.5s ease;
  pointer-events: none;
}
.build-card:hover { border-color: rgba(110, 231, 255, 0.42); background: linear-gradient(165deg, rgba(30, 52, 82, 0.65), rgba(12, 20, 36, 0.7)); transform: translateY(-2px); }
.build-card:hover::after { transform: translateX(100%); }
.build-card.locked { cursor: not-allowed; opacity: 0.55; }
.build-card.locked:hover { transform: none; border-color: rgba(126, 190, 255, 0.14); }
.build-card.poor { border-color: rgba(255, 107, 129, 0.2); }
.build-card-top { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; }
.build-icon {
  width: 36px; height: 36px; border-radius: 9px;
  display: grid; place-items: center;
  background: rgba(110, 231, 255, 0.08);
  border: 1px solid rgba(110, 231, 255, 0.18);
  color: var(--cyan);
}
.build-icon svg { width: 19px; height: 19px; }
.build-size { font-family: var(--mono); font-size: 7.5px; color: #657494; letter-spacing: 0.08em; }
.build-name { font-size: 12.5px; font-weight: 700; color: #e7f2ff; letter-spacing: 0.01em; }
.build-desc { font-size: 10px; line-height: 1.45; color: #8fa1c2; min-height: 29px; }
.build-meta { display: flex; flex-wrap: wrap; gap: 5px; margin-top: auto; }
.build-cost, .build-out {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 3px 6px; border-radius: 4px;
  background: rgba(255, 255, 255, 0.035);
  font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.02em;
  color: #a9b9d8;
}
.build-cost svg, .build-out svg { width: 11px; height: 11px; }
.build-cost.insufficient { color: var(--red); background: rgba(255, 107, 129, 0.09); }
.build-lock {
  position: absolute; inset: auto 12px 12px 12px;
  display: flex; align-items: center; gap: 6px;
  padding: 7px 9px;
  border-radius: 5px;
  background: rgba(5, 8, 16, 0.88);
  border: 1px solid rgba(255, 209, 102, 0.22);
  font-family: var(--mono); font-size: 8px; color: var(--gold);
  letter-spacing: 0.06em;
}
.build-lock svg { width: 12px; height: 12px; }
.build-badge {
  position: absolute; top: 10px; right: 10px;
  padding: 3px 6px; border-radius: 4px;
  background: rgba(125, 255, 178, 0.1);
  border: 1px solid rgba(125, 255, 178, 0.25);
  color: var(--green); font-family: var(--mono); font-size: 7px; letter-spacing: 0.08em;
}

/* build placement banner */
.build-mode #action-hint { opacity: 0; }
#build-banner {
  position: absolute; left: 50%; bottom: 132px; transform: translateX(-50%);
  display: flex; align-items: center; gap: 10px;
  padding: 9px 16px;
  border: 1px solid rgba(181, 140, 255, 0.4);
  border-radius: 99px;
  background: rgba(12, 8, 26, 0.9);
  backdrop-filter: blur(12px);
  font-family: var(--mono); font-size: 9px; letter-spacing: 0.08em; color: #d9c9ff;
  z-index: 13;
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.45);
}
#build-banner b { color: #fff; }
#build-banner .bb-cost { color: var(--gold); }
#build-banner .bb-cancel { color: #8477a5; }

/* ============================================================
   MAP
   ============================================================ */

.map-shell { width: min(1240px, 100%); }
.map-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 340px;
  gap: 16px;
  margin-top: 16px;
  height: min(58vh, 560px);
}
.map-stage {
  position: relative;
  border: 1px solid rgba(126, 190, 255, 0.12);
  border-radius: 12px;
  overflow: hidden;
  background: #05070f;
  min-height: 320px;
}
#orbit-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; cursor: pointer; touch-action: none; }
.map-legend {
  position: absolute; left: 12px; bottom: 11px;
  display: flex; gap: 14px;
  padding: 6px 10px;
  border: 1px solid rgba(126, 190, 255, 0.12);
  border-radius: 6px;
  background: rgba(5, 9, 18, 0.72);
  backdrop-filter: blur(8px);
  font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.1em; color: #7f90b4;
}
.map-legend span { display: flex; align-items: center; gap: 5px; }
.dot { width: 6px; height: 6px; border-radius: 50%; display: inline-block; }
.dot.current { background: var(--cyan); box-shadow: 0 0 7px var(--cyan); }
.dot.claimed { background: var(--green); }
.dot.open { background: #5b6a88; }

.map-side { padding: 18px; display: flex; flex-direction: column; gap: 13px; overflow: auto; }
.map-status { display: inline-flex; align-items: center; gap: 7px; font-family: var(--mono); font-size: 8px; letter-spacing: 0.14em; }
.map-status .dot { width: 7px; height: 7px; }
.map-status.cur { color: var(--cyan); }
.map-status.claimed { color: var(--green); }
.map-status.open { color: #8999ba; }
.map-status.locked { color: var(--gold); }
.map-name { font-size: 34px; font-weight: 900; line-height: 0.9; letter-spacing: -0.03em; color: #f2f9ff; margin: -2px 0 0; }
.map-type { font-family: var(--mono); font-size: 8.5px; letter-spacing: 0.16em; color: #7182a5; }
.map-desc { font-size: 11px; line-height: 1.55; color: #95a7c6; margin: 0; }
.map-perks { display: flex; flex-wrap: wrap; gap: 5px; }
.perk { padding: 4px 7px; border-radius: 4px; background: rgba(110, 231, 255, 0.07); border: 1px solid rgba(110, 231, 255, 0.14); font-family: var(--mono); font-size: 7.5px; color: #a9e9ff; }
.map-rows { display: flex; flex-direction: column; gap: 7px; padding: 11px 0; border-top: 1px solid rgba(126, 190, 255, 0.1); border-bottom: 1px solid rgba(126, 190, 255, 0.1); }
.map-row { display: flex; align-items: center; justify-content: space-between; font-family: var(--mono); font-size: 8.5px; color: #7d8eaf; }
.map-row b { color: #d6e5ff; font-weight: 700; }
.map-row b.ok { color: var(--green); }
.map-row b.bad { color: var(--red); }
.map-note { font-family: var(--mono); font-size: 8px; line-height: 1.6; color: #7182a5; }
.map-side .btn { width: 100%; margin-top: auto; }
.map-side .btn:disabled { opacity: 0.45; cursor: not-allowed; transform: none; filter: grayscale(0.4); }
.map-foot { flex-wrap: wrap; }
.planet-switch { display: flex; gap: 5px; flex-wrap: wrap; }
.planet-pill {
  display: flex; align-items: center; gap: 6px;
  padding: 4px 9px;
  border: 1px solid rgba(126, 190, 255, 0.14);
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.025);
  color: #8fa1c2;
  font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.08em;
  cursor: pointer;
  transition: all 0.15s ease;
}
.planet-pill:hover { color: #fff; border-color: rgba(110, 231, 255, 0.4); }
.planet-pill.selected { color: #fff; border-color: rgba(110, 231, 255, 0.55); background: rgba(110, 231, 255, 0.09); }
.planet-pill i { width: 6px; height: 6px; border-radius: 50%; }

.travel-screen {
  position: absolute; left: 50%; bottom: 46px; transform: translateX(-50%);
  z-index: 60;
  width: min(380px, calc(100vw - 40px));
}
.travel-card {
  padding: 15px 18px;
  border: 1px solid rgba(110, 231, 255, 0.32);
  border-radius: 10px;
  background: rgba(6, 12, 24, 0.95);
  backdrop-filter: blur(16px);
  box-shadow: 0 24px 70px rgba(0, 0, 0, 0.55);
}
.travel-kicker { font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.24em; color: var(--cyan); }
.travel-dest { margin: 4px 0 10px; font-size: 22px; font-weight: 900; letter-spacing: 0.08em; color: #f1faff; }
.travel-bar { height: 4px; border-radius: 99px; background: rgba(126, 190, 255, 0.12); overflow: hidden; }
.travel-bar span { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, var(--cyan), var(--violet)); box-shadow: 0 0 12px var(--cyan); transition: width 0.1s linear; }
.travel-sub { margin-top: 8px; font-family: var(--mono); font-size: 8px; letter-spacing: 0.06em; color: #7384a6; }

/* ============================================================
   HELP
   ============================================================ */

.help-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 18px; }
.help-card { padding: 15px 16px; border: 1px solid rgba(126, 190, 255, 0.12); border-radius: 10px; background: rgba(16, 26, 45, 0.38); }
.help-card.wide { grid-column: 1 / -1; }
.help-card h3 { margin: 0 0 10px; font-family: var(--mono); font-size: 8.5px; letter-spacing: 0.2em; color: var(--cyan); font-weight: 700; }
.help-card p { margin: 0 0 8px; font-size: 11.5px; line-height: 1.65; color: #9aaccb; }
.help-card p:last-child { margin-bottom: 0; }
.help-card b { color: #dceaff; }
