53: const ICON_BY_RES = {
54:   energy: 'energy', water: 'water', food: 'food',
55:   materials: 'materials', credits: 'credits', research: 'research',
56: };
57: 
58: function icon(name, cls = '') {
59:   const body = ICONS[name] || ICONS.star;
60:   return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${body}</svg>`;
61: }
62: 
63: function esc(str) {
64:   return String(str).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
65: }
66: 
67: function rewardLabel(reward) {
68:   if (!reward) return '';
69:   const parts = [];
70:   for (const [key, value] of Object.entries(reward)) {
71:     const meta = RESOURCES.find((r) => r.key === key);
72:     parts.push(`+${formatNumber(value)} ${meta?.short || key.toUpperCase()}`);
73:   }
74:   return parts.join(' · ');
75: }
76: 
77: function costChips(cost, state) {
78:   return Object.entries(cost || {}).map(([key, value]) => {
79:     const meta = RESOURCES.find((r) => r.key === key);
80:     const short = meta?.short || key.slice(0, 2).toUpperCase();
81:     const enough = (state.resources[key] || 0) + 1e-6 >= value;
82:     return `<span class="build-cost ${enough ? '' : 'insufficient'}">${icon(ICON_BY_RES[key] || 'materials')}${value} ${short}</span>`;
83:   }).join('');
84: }
