278:     const knob = stick.querySelector('.joystick-knob');
279:     let pointerId = null;
280:     let center = { x: 0, y: 0 };
281:     const reset = () => {
282:       pointerId = null;
283:       knob.style.transform = 'translate(-50%, -50%)';
284:       this.game.touch.x = 0;
285:       this.game.touch.y = 0;
286:     };
287:     const update = (e) => {
288:       const dx = e.clientX - center.x;
289:       const dy = e.clientY - center.y;
290:       const max = 36;
291:       const len = Math.hypot(dx, dy) || 1;
292:       const k = Math.min(1, max / len);
293:       const ox = dx * k;
294:       const oy = dy * k;
295:       knob.style.transform = `translate(calc(-50% + ${ox}px), calc(-50% + ${oy}px))`;
296:       const nx = ox / max;
297:       const ny = oy / max;
298:       this.game.touch.x = Math.abs(nx) > 0.16 ? nx : 0;
299:       this.game.touch.y = Math.abs(ny) > 0.16 ? ny : 0;
300:     };
301:     stick.addEventListener('pointerdown', (e) => {
302:       e.preventDefault();
303:       pointerId = e.pointerId;
304:       stick.setPointerCapture(pointerId);
305:       const rect = stick.getBoundingClientRect();
306:       center = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
307:       update(e);
308:     });
309:     stick.addEventListener('pointermove', (e) => {
310:       if (pointerId !== e.pointerId) return;
311:       e.preventDefault();
312:       update(e);
313:     });
314:     stick.addEventListener('pointerup', reset);
315:     stick.addEventListener('pointercancel', reset);
316:     stick.addEventListener('lostpointercapture', reset);
