368:     const planet = state.planets[state.planetId];
369:     const def = planetById(state.planetId);
370:     const cards = [];
371:     for (const type of BUILD_ORDER) {
372:       const bd = BUILDINGS[type];
373:       if (!bd || bd.hidden) continue;
374:       if (type === 'beacon' && planet.claimed) continue;
375:       let lock = '';
376:       if (!planet.claimed && !bd.claim) lock = 'Reivindique o planeta primeiro';
377:       else if ((state.resources.research || 0) < (bd.research || 0)) lock = `Requer ${bd.research} de pesquisa`;
378:       const poor = !canAfford(state, bd.cost);
379:       const outputs = bd.output && Object.keys(bd.output).length
380:         ? Object.entries(bd.output).map(([key, value]) => {
381:           const meta = RESOURCES.find((r) => r.key === key);
382:           return `<span class="build-out">${icon(ICON_BY_RES[key] || 'materials')}+${value} ${meta?.short || ''}</span>`;
383:         }).join('')
384:         : '';
385:       const special = bd.claim ? '<span class="build-out">REIVINDICA PLANETA</span>'
386:         : type === 'pad' ? '<span class="build-out">VIAGENS -25%</span>'
387:           : type === 'habitat' ? `<span class="build-out">CAPACIDADE +${bd.cap}</span>` : '';
388:       cards.push(`
389:         <button class="build-card ${lock ? 'locked' : ''} ${poor ? 'poor' : ''}" data-build="${type}" title="${esc(bd.desc)}">
390:           <div class="build-card-top">
391:             <div class="build-icon">${icon(bd.icon || 'home')}</div>
392:             <div class="build-size">${bd.size[0]}×${bd.size[1]} · ${bd.claim ? 'SETOR' : 'BASE'}</div>
393:           </div>
394:           <div class="build-name">${bd.name}</div>
395:           <div class="build-desc">${esc(bd.desc)}</div>
396:           <div class="build-meta">
397:             ${costChips(bd.cost, state)}
398:             ${outputs}
399:             ${special}
400:           </div>
401:           ${lock ? `<div class="build-lock">${icon('lock')}${lock}</div>` : ''}
402:         </button>
403:       `);
404:     }
405:     this.refs.buildGrid.innerHTML = cards.join('');
406:     this.refs.buildFootnote.textContent = !planet.claimed
407:       ? `Setor ${def.name.toUpperCase()} não reivindicado — construa um farol para fundar a colônia.`
408:       : `Setor ${def.name.toUpperCase()} reivindicado · ${planet.buildings.length} estruturas · os recursos são consumidos ao posicionar.`;
409:   }
