255: export function isCircleBlocked(planet, x, y, radius = 9) {
256:   const minX = x - radius;
257:   const maxX = x + radius;
258:   const minY = y - radius;
259:   const maxY = y + radius;
260:   if (minX < TILE * 0.3 || minY < TILE * 0.3) return true;
261:   if (maxX > WORLD_W * TILE - TILE * 0.3 || maxY > WORLD_H * TILE - TILE * 0.3) return true;
262: 
263:   const checks = [
264:     [x, y],
265:     [minX, minY],
266:     [maxX, minY],
267:     [minX, maxY],
268:     [maxX, maxY],
269:     [x, minY],
270:     [x, maxY],
271:     [minX, y],
272:     [maxX, y],
273:   ];
274:   for (const [px, py] of checks) {
275:     const tx = Math.floor(px / TILE);
276:     const ty = Math.floor(py / TILE);
277:     if (!inBounds(tx, ty)) return true;
278:     if (!isWalkableTile(tileAt(planet, tx, ty))) return true;
279:   }
280: 
281:   for (const b of planet.buildings) {
282:     const rx = b.tx * TILE + 1;
283:     const ry = b.ty * TILE + 1;
284:     const rw = b.w * TILE - 2;
285:     const rh = b.h * TILE - 2;
286:     const cx = clamp(x, rx, rx + rw);
287:     const cy = clamp(y, ry, ry + rh);
288:     const dx = x - cx;
289:     const dy = y - cy;
290:     if (dx * dx + dy * dy < (radius - 3) * (radius - 3)) return true;
291:   }
292:   return false;
293: }
