/* ============================================================
   COLÔNIA AURORA — interface
   ============================================================ */

:root {
  --bg: #05060d;
  --bg-2: #070a15;
  --panel: rgba(9, 15, 29, 0.78);
  --panel-solid: #0a1020;
  --cyan: #6ee7ff;
  --cyan-soft: #a9f6ff;
  --violet: #b58cff;
  --gold: #ffd166;
  --green: #7dffb2;
  --orange: #ff9a63;
  --red: #ff6b81;
  --text: #e9f1ff;
  --muted: #8b9abd;
  --faint: #5d6a88;
  --line: rgba(126, 190, 255, 0.16);
  --line-strong: rgba(126, 190, 255, 0.36);
  --font: "Segoe UI", "Avenir Next", "Helvetica Neue", system-ui, sans-serif;
  --mono: "SFMono-Regular", "Cascadia Mono", "Roboto Mono", Menlo, Consolas, monospace;
  --r: 14px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button { font-family: inherit; }
button, [role="button"] { -webkit-tap-highlight-color: transparent; }
.hidden { display: none !important; }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }

#app { position: fixed; inset: 0; overflow: hidden; }

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  background: #05060d;
  touch-action: none;
  cursor: crosshair;
}

kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 19px;
  height: 19px;
  padding: 0 5px;
  border: 1px solid rgba(150, 200, 255, 0.24);
  border-bottom-color: rgba(150, 200, 255, 0.4);
  border-radius: 5px;
  background: rgba(10, 18, 34, 0.9);
  color: #b9caea;
  font-family: var(--mono);
  font-size: 10px;
  line-height: 1;
  letter-spacing: 0.02em;
}

/* ============================================================
   TITLE
   ============================================================ */

#title-screen {
  position: absolute;
  inset: 0;
  z-index: 30;
  display: flex;
  flex-direction: column;
  padding: clamp(18px, 3vw, 38px) clamp(20px, 5vw, 72px) clamp(14px, 2.4vw, 28px);
  background:
    linear-gradient(90deg, rgba(4, 6, 14, 0.94) 0%, rgba(4, 6, 14, 0.72) 38%, rgba(4, 6, 14, 0.16) 72%, rgba(4, 6, 14, 0.42) 100%),
    radial-gradient(ellipse at 20% 80%, rgba(110, 231, 255, 0.07), transparent 55%),
    radial-gradient(ellipse at 85% 15%, rgba(181, 140, 255, 0.08), transparent 55%);
  pointer-events: auto;
}

#title-screen::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.014) 0 1px, transparent 1px 3px);
  opacity: 0.55;
  mix-blend-mode: overlay;
}

.title-grain {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.25;
  background-image:
    radial-gradient(circle at 12% 24%, rgba(255,255,255,.05) 0 1px, transparent 1.6px),
    radial-gradient(circle at 62% 78%, rgba(255,255,255,.04) 0 1px, transparent 1.6px);
  background-size: 170px 170px, 230px 230px;
}

.title-topline {
  display: flex;
  justify-content: space-between;
  align-items: center;

