  try {
    await btn.click({ trial: true, timeout: 2000 });
    console.log(i, 'OK', JSON.stringify(info));
  } catch(e) {
    console.log(i, 'FAIL', JSON.stringify(info), e.message.split('\n').slice(0,20).join(' | '));
  }
  await page.close();
}
await browser.close();

