import { createRequire } from 'node:module';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
for (let i = 0; i < 6; i++) {
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto('http://localhost:3000', { waitUntil: 'load' });
  await page.waitForFunction(() => document.fonts.status === 'loaded');
  const raf = await page.evaluate(() => new Promise(res => { let n = 0; const t0 = performance.now(); function f() { n++; if (performance.now() - t0 < 1000) requestAnimationFrame(f); else res({ n, ms: performance.now() - t0, clock: window.__colonia?.clock }); } requestAnimationFrame(f); }));
  const btn = page.locator('#btn-play');
  const t0 = Date.now();
  let result;
  try { await btn.click({ trial: true, timeout: 2000 }); result = 'OK'; }
  catch (e) { result = e.message.split('\n').slice(0, 14).join(' | '); }
  console.log(i, JSON.stringify(raf), 'trialMs=' + (Date.now() - t0), result);
  await page.close();
}
await browser.close();

