const measure = page => page.evaluate(() => new Promise(res => { let n = 0; const t0 = performance.now(); const gaps = []; let prev = t0; function f() { n++; const now = performance.now(); gaps.push(Math.round(now - prev)); prev = now; if (now - t0 < 2500) requestAnimationFrame(f); else res({ n, ms: Math.round(now - t0), gaps: gaps.slice(0, 12) }); } requestAnimationFrame(f); }));
{
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto('about:blank');
  console.log('blank', JSON.stringify(await measure(page)));
  await page.close();
}
{
