/* ============================================================
   ANIMATIONS
   ============================================================ */

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.45; }
}
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes toastIn {
  from { opacity: 0; transform: translateY(-10px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes toastOut {
  to { opacity: 0; transform: translateY(-8px) scale(0.98); }
}
@keyframes chipPulse {
  0% { border-color: rgba(110, 231, 255, 0.7); background: rgba(40, 90, 120, 0.6); }
  100% { border-color: rgba(126, 190, 255, 0.1); background: rgba(14, 23, 41, 0.4); }
}

